llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Pentosan polysulfate, a highly sulfated polysaccharide, had absolute oral bioavailability of only 0.5-1% in healthy subjects after 400 mg daily oral dosing, directly demonstrating that heavily sulfated carbohydrate structures are very poorly absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Dextran sulfate, another highly sulfated polysaccharide, is reported to have poor oral bioavailability in humans, reinforcing the poor absorption of sulfated carbohydrate polymers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Zanamivir, a polar sialic-acid derivative bearing N-acetyl, carboxylate, and multiple hydroxyl groups, has an absolute oral bioavailability of only 2% (range 1-5%) in volunteers, closely matching the query's polar acidic sugar features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Acamprosate, an N-acetylated sulfonate, has an absolute oral bioavailability of approximately 11% under fasting conditions in humans, below the 20% threshold, showing that even smaller N-acetyl/sulfonate structures do not achieve adequate oral bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a highly polar, ionized sulfated disaccharide with N-acetyl, carboxylate, and multiple hydroxyls. High-transfer experimental analogues—pentosan polysulfate (F 0.5-1%), dextran sulfate (poor), zanamivir (F 2%), and acamprosate (F 11%)—all show oral bioavailability well below 20%. Low-transfer high-F compounds such as oseltamivir and idarubicin are structurally dissimilar and do not apply. Therefore the prediction is low.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the exact query disaccharide; extrapolation relies on close polar saccharide analogues.",
    "Possible active uptake or transporter-mediated absorption was not experimentally assessed for the query.",
    "Exact human absolute bioavailability for the query molecule is not available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

